def is_base64_file_input(obj: object) -> TypeGuard[Base64FileInput]:
    if isinstance(obj, (str, os.PathLike, bytes)):
        return True
    if isinstance(obj, io.IOBase) and not isinstance(obj, io.TextIOBase):
        return True
    if hasattr(obj, "read") and callable(getattr(obj, "read")) and not isinstance(obj, io.TextIOBase):
        return True
    return False


def is_file_content(obj: object) -> TypeGuard[FileContent]:
    if isinstance(obj, (bytes, str, os.PathLike)):
        return True
    if isinstance(obj, io.IOBase) and not isinstance(obj, io.TextIOBase):
        return (not hasattr(obj, "readable") or obj.readable()) and (not hasattr(obj, "closed") or not obj.closed)
    if hasattr(obj, "read") and callable(getattr(obj, "read")) and not isinstance(obj, io.TextIOBase):
        return (not hasattr(obj, "readable") or obj.readable()) and (not hasattr(obj, "closed") or not obj.closed)
    return False


def assert_is_file_content(obj: object, *, key: str | None = None) -> FileContent:
    if not is_file_content(obj):
        prefix = f"Expected entry at `{key}`" if key is not None else "Expected file input"
        raise TypeError(
            f"{prefix} to be bytes, a readable IO stream, a string, or PathLike, but received {type(obj)} instead."
        )
    return cast(FileContent, obj)


