def to_httpx_files(files: RequestFiles | None) -> HttpxRequestFiles | None:
    if files is None:
        return None

    if isinstance(files, (str, bytes)):
        raise TypeError(f"Unexpected file type input {type(files)}, expected mapping or sequence")

    if is_mapping_t(files):
        result_dict: dict[str, HttpxFileTypes] = {}
        for key, file in files.items():
            if not isinstance(key, str):
                raise TypeError(f"Expected file field name to be a string, but received {key!r} of type {type(key)}")
            result_dict[key] = _transform_file(file, key=key)
        return result_dict

    if is_sequence_t(files):
        result_list: list[tuple[str, HttpxFileTypes]] = []
        for item in files:
            if not (is_tuple_t(item) and len(item) == 2 and isinstance(item[0], str)):
                raise TypeError(f"Expected sequence of (key, file) pairs, but received element {item!r} of type {type(item)}")
            key, file = item
            result_list.append((key, _transform_file(file, key=key)))
        return result_list

    raise TypeError(f"Unexpected file type input {type(files)}, expected mapping or sequence")


def _transform_file(file: FileTypes, *, key: str | None = None) -> HttpxFileTypes:
    if isinstance(file, os.PathLike):
        raw_path = os.fspath(file)
        if isinstance(raw_path, bytes):
            raw_path = os.fsdecode(raw_path)
        path = pathlib.Path(raw_path)
        if not path.name:
            prefix = f"Entry at `{key}`" if key is not None else "File path"
            raise TypeError(f"{prefix} has no filename: {path}")
        return (path.name, read_file_content(file, key=key))

    if is_tuple_t(file):
        if not (2 <= len(file) <= 4):
            prefix = f"For entry `{key}`, expected" if key is not None else "Expected"
            raise TypeError(f"{prefix} file tuple to have 2, 3, or 4 elements, but received {len(file)} elements in {file!r}")

        filename = file[0]
        if not (filename is None or isinstance(filename, str)):
            prefix = f"For entry `{key}`, expected" if key is not None else "Expected"
            raise TypeError(f"{prefix} file name in tuple to be str or None, but received {filename!r} of type {type(filename)}")

        content = read_file_content(file[1], key=key)

        if len(file) >= 3:
            content_type = file[2]
            if not (content_type is None or isinstance(content_type, str)):
                prefix = f"For entry `{key}`, expected" if key is not None else "Expected"
                raise TypeError(f"{prefix} content type in tuple to be str or None, but received {content_type!r} of type {type(content_type)}")

        if len(file) == 4:
            headers = file[3]
            if not (headers is None or is_mapping(headers) or is_mapping_t(headers)):
                prefix = f"For entry `{key}`, expected" if key is not None else "Expected"
                raise TypeError(f"{prefix} custom headers in tuple to be a mapping or None, but received {headers!r} of type {type(headers)}")

        return (file[0], content, *file[2:])

    assert_is_file_content(file, key=key)
    return file


def read_file_content(file: FileContent, *, key: str | None = None) -> HttpxFileContent:
    if isinstance(file, os.PathLike):
        raw_path = os.fspath(file)
        if isinstance(raw_path, bytes):
            raw_path = os.fsdecode(raw_path)
        path = pathlib.Path(raw_path)
        prefix = f"Error reading file for `{key}` at" if key is not None else "Error reading file at"
        if path.is_dir():
            raise TypeError(f"{prefix} directory path: {path}")
        if not path.name:
            raise TypeError(f"{prefix} empty filename path: {path}")
        try:
            return path.read_bytes()
        except OSError as err:
            raise RuntimeError(f"{prefix} {path}: {err}") from err

    if hasattr(file, "seek") and hasattr(file, "tell"):
        try:
            if not hasattr(file, "seekable") or file.seekable():
                file.seek(0)
        except (OSError, io.UnsupportedOperation, AttributeError):
            pass

    return file


